import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() -> Result<(), conc.TimeoutError> {
    let ch: conc.Channel<Int64> = conc.channel(1)
    let r = scope timeout(30) {
        let t = task effect io {
            let v = ch.receive()
        }
        let _ = t.await()
    }
    let _ = r?
    return Ok(())
}
